 let entries=sportCatalogEntries().filter(ex=>{const id=ex.id,equipment=Array.isArray(ex.equipment)?ex.equipment:[ex.equipment].filter(Boolean),muscles=ex.primaryMuscles||ex.primary_muscles||[];return (!q||[...Object.values(ex.names||{}),ex.name,ex.equipment].flat().join(' ').toLocaleLowerCase().includes(q))&&(!focus.length||muscles.some(m=>focus.includes(m)))&&(!sportLibraryEquipment||equipment.includes(sportLibraryEquipment))&&(!sportLibraryCategory||ex.category===sportLibraryCategory)&&(sportLibraryTab!=='favorites'||favorite.has(id))&&(sportLibraryTab!=='recent'||recent.includes(id))&&(sportLibraryTab!=='custom'||ex.custom);});
