 return `<section class="sport-library-panel" aria-label="${esc(sportText('library'))}"><div class="panel-head"><h2>${sportText('library')}</h2>${workoutDraft?`<button class="btn small" data-sport-panel-close aria-label="${esc(sportText('close'))}">×</button>`:''}</div>${search}${tabs}${sportFocusMarkup()}${filters}${cards}${create}</section>`;
