function sportEditorScheduleMarkup(){const events=sportPlans().filter(e=>e.workoutTemplateId===workoutDraft.id),event=events.find(e=>e.id===sportPlanEventId);return `<section class="sport-library-panel sport-inline-schedule"><div class="panel-head"><h2>${sportText('schedule')}</h2><button class="btn small" data-sport-panel-close aria-label="${esc(sportText('close'))}">×</button></div><p class="muted">${esc(pathSystemTimeZone())}</p><label>${sportText('day')}<input type="date" id="sport-plan-date" value="${esc(event?.date||homeDate||pathToday())}"></label><label>${sportText('time')}<input type="time" id="sport-plan-time" step="900" value="${esc(clockTime(event?.hour??18))}"></label><button class="btn primary" data-sport-plan-confirm>${sportText('confirmSchedule')}</button><h3>${sportText('scheduled')}</h3>${events.map(e=>`<article class="sport-scheduled-row"><button class="note-open" data-event="${esc(e.id)}">${esc(e.title)}<small>${pretty(e.date)} · ${clockTime(e.hour)}</small></button><button class="btn small" data-sport-plan-move="${esc(e.id)}">${sportText('move')}</button></article>`).join('')||`<p class="muted">${sportText('noScheduled')}</p>`}</section>`;}
