function sportOpenShort(templateId,calendarId){const event=data.events.find(e=>e.id===calendarId),template=event?.fullWorkoutSnapshot||event?.plannedSnapshot||data.workouts.find(w=>w.id===templateId);if(!template?.exercises?.length)return;if(data.activeWorkout){toast('Finish or save your active workout before planning another session.');return;}sportShortDraft={template:pathClone(template),calendarId:calendarId||null,date:event?.date||pathToday(),start:null};render();}
function sportShortOptions(draft){const slots=sportAvailableWindows(draft.date,draft.calendarId);return slots.flatMap(slot=>{const full=sportEstimate(draft.template),budget=Math.min(slot.minutes,Math.max(15,Math.floor(full.minutes*.65/15)*15));const short=sportShortTemplate(draft.template,budget);return short?[{...slot,short}]:[];});}
function sportShortPage(){const draft=sportShortDraft,full=sportEstimate(draft.template),options=sportShortOptions(draft),chosen=options.find(o=>o.start===draft.start)||options[0];return `<div class="sport-design sport-v3"><button class="back-link" data-sport-short-close>← Back to Sport</button>${sportDesignHeader('Make room for practice',draft.template.name+' · review before applying')}<section class="panel sport-short-review"><label>Calendar day<input type="date" data-sport-short-date value="${draft.date}"></label><p class="muted">${pathSystemTimeZone()} · Busy events, travel and protected free time remain blocked.</p><h2>Choose a real opening</h2><div class="sport-slot-list">${options.map(o=>`<button class="btn" data-sport-short-slot="${o.start}" aria-pressed="${chosen?.start===o.start}">${clockTime(pathZoneParts(o.start).hour)}–${clockTime(pathZoneParts(o.end).hour)} · ${o.minutes} min free</button>`).join('')||'<p>No suitable opening on this day. Choose another day or move the full workout.</p>'}</div>${chosen?`<h3>Short session · approximately ${chosen.short.estimate.minutes} min</h3><ul>${chosen.short.changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p class="muted">Estimate: 5 min warm-up + ${Math.ceil(chosen.short.estimate.work/60)} min work + ${Math.ceil(chosen.short.estimate.rest/60)} min rest + transitions. Assumes 3 seconds per rep or 40 seconds per weighted set; adjust for your pace.</p><button class="btn primary" data-sport-short-apply="${chosen.start}">Schedule this short session</button>`:''}<hr><h3>Keep the full workout · approximately ${full.minutes} min</h3><p class="muted">Review the next available slot before moving anything.</p><button class="btn" data-sport-move-full>Find full-workout slot</button>${draft.move?`<div class="sport-move-review"><strong>${pretty(draft.move.date)} · ${clockTime(draft.move.hour)} · ${draft.move.duration} min</strong><button class="btn primary" data-sport-move-confirm>Confirm ${draft.calendarId?'move':'schedule'}</button></div>`:''}<p class="muted">Only the scheduled session changes. Existing templates and completed history remain intact.</p></section></div>`;}
function sportCommitShort(start){const draft=sportShortDraft;if(!draft)return false;const option=sportShortOptions(draft).find(o=>o.start===start);if(!option){toast('This opening changed. Choose another slot.');render();return false;}
 const existing=data.events.find(e=>e.id===draft.calendarId);if(existing?.done){toast('This session is already complete.');return false;}
 const base={...(existing||{}),id:existing?.id||uid(),title:draft.template.name+' · Short session',date:draft.date,hour:0,type:'workout',duration:option.short.template.duration,workoutTemplateId:draft.template.id,plannedSnapshot:pathClone(option.short.template),fullWorkoutSnapshot:pathClone(draft.template),sportMode:'short',done:false};
 const candidate=pathSlotEvent(base,start);if(calendarConflicts(candidate).length){toast('This window is no longer free.');return false;}
 const ok=sportTry(()=>{if(existing)Object.assign(existing,candidate);else data.events.push(candidate);});if(ok){sportShortDraft=null;render();toast('Short session scheduled. Original template unchanged.');}return ok;
}
function sportFindFullSlot(){const draft=sportShortDraft;if(!draft)return;const existing=data.events.find(e=>e.id===draft.calendarId),base={...(existing||{}),id:existing?.id||uid(),title:draft.template.name,type:'workout',date:draft.date,hour:8,duration:Math.max(15,Math.ceil(sportEstimate(draft.template).minutes/15)*15),workoutTemplateId:draft.template.id,plannedSnapshot:pathClone(draft.template),sportMode:'full',done:false};let candidate=null;for(let day=0;day<14&&!candidate;day++){const slot=sportAvailableWindows(addDays(draft.date,day),draft.calendarId).find(s=>s.minutes>=base.duration);if(slot)candidate=pathSlotEvent(base,slot.start);}draft.move=candidate;if(!candidate)toast('No free slot fits this workout in the next 14 days.');render();}
function sportCommitFullSlot(){const draft=sportShortDraft,candidate=draft?.move;if(!candidate)return false;const existing=data.events.find(e=>e.id===draft.calendarId);if(existing?.done||calendarConflicts(candidate).length||pathEventTiming(candidate).start<Date.now()){toast('This slot changed. Find another opening.');return false;}const ok=sportTry(()=>{if(existing)Object.assign(existing,candidate);else data.events.push(candidate);});if(ok){sportShortDraft=null;render();toast('Full workout scheduled');}return ok;}
document.addEventListener('input',e=>{if(sportPackageInput(e))return;const id=e.target.dataset.smartResult;if(!id)return;const s=data.activeWorkout?.sets.find(s=>s.id===id);if(!s||s.done||Number.isFinite(data.activeWorkout.pausedAt))return;sportPendingInputs[id]={...(sportPendingInputs[id]||{}),result:e.target.value};delete sportSetErrors[id];const ok=sportSaveInput(),hint=document.getElementById('set-error-'+id);if(hint)hint.textContent=ok?'':'Not saved · draft retained. Retry logging this set.';});
document.addEventListener('change',e=>{if(sportPackageChange(e))return;const t=e.target;if(t.dataset.smartKind){const s=data.activeWorkout?.sets.find(s=>s.id===t.dataset.smartKind);if(s&&!s.done&&SPORT_KINDS.includes(t.value)){sportPendingInputs[s.id]={...(sportPendingInputs[s.id]||{}),kind:t.value};sportSaveInput();}}if(t.hasAttribute('data-sport-short-date')&&sportShortDraft){if(pathValidDate(t.value)){sportShortDraft.date=t.value;sportShortDraft.start=null;delete sportShortDraft.move;render();}}if(workoutDraft&&t.dataset.exerciseId&&t.dataset.exerciseField){const ex=workoutDraft.exercises.find(x=>x.id===t.dataset.exerciseId);if(ex){ex[t.dataset.exerciseField]=t.value;pathContextQueueWorkout();}}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.dataset.sportActual){e.preventDefault();document.querySelector(`[data-smart-log="${CSS.escape(e.target.dataset.setId)}"]`)?.click();return;}if(e.key==='Enter'&&e.target.dataset.smartResult){e.preventDefault();document.querySelector(`[data-smart-log="${e.target.dataset.smartResult}"]`)?.click();}});
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-sport-session-pause],[data-sport-rest-toggle],[data-sport-rest-skip],[data-sport-slot-select],[data-sport-editor-schedule],[data-sport-editor-start],[data-sport-panel-close],[data-sport-library-tab],[data-sport-library-plus],[data-sport-details],[data-sport-favorite],[data-sport-custom-new],[data-sport-preset],[data-sport-muscle],[data-sport-map-view],[data-sport-focus-clear],[data-sport-plan-confirm],[data-sport-plan-move],[data-sport-program-copy],[data-sport-program-archive],[data-sport-template-copy],[data-sport-template-archive],[data-sport-show-archived],[data-sport-section],[data-sport-exercise],[data-sport-preference],[data-sport-program-notes],[data-sport-swap],[data-sport-skill],[data-smart-log],[data-smart-undo],[data-smart-rest],[data-smart-retry],[data-sport-finish],[data-sport-short],[data-sport-short-close],[data-sport-short-slot],[data-sport-short-apply],[data-sport-move-full],[data-sport-move-confirm],[data-sport-library-add],[data-sport-progression]');if(!b)return;
 if(editor&&!b.closest('#editor-overlay')&&!closeEditor())return;
 const d=b.dataset;if(sportPackageAction(b))return;
 if(d.sportSection){sportSection=d.sportSection;sportLastFinished=null;render();return;}
 if(d.sportExercise){sportCurrentExercise=d.sportExercise;render();return;}
 if(d.sportPreference)return sportPreferenceEditor(d.sportPreference);
 if(d.sportProgramNotes)return sportProgramNotes(d.sportProgramNotes);
 if(d.sportSwap)return sportSwapEditor(d.sportSwap);
 if(d.sportSkill)return sportSkillEditor(d.sportSkill);
 if('sportLibraryAdd'in d)return sportAddLibraryExercise();
 if(d.sportProgression)return sportProgressionEditor(d.templateId,d.sportProgression);
 if('sportFinish'in d)return sportFinish();
 if(d.smartRest)return data.activeWorkout?.sportVersion===4?sportCoreCommand({type:'rest',activeId:data.activeWorkout.id,action:'extend',seconds:Math.max(0,Number(d.smartRest))}):sportTry(()=>sportAdjustRest(data.activeWorkout,Number(d.smartRest)));
 if('smartRetry'in d){sportSaveInput();render();return;}
 if(d.smartUndo)return data.activeWorkout?.sportVersion===4?sportCoreCommand({type:'undoSet',activeId:data.activeWorkout.id,setId:d.smartUndo}):sportTry(()=>sportUndoSet(data.activeWorkout,d.smartUndo));
 if(d.smartLog){const a=data.activeWorkout,s=a?.sets.find(x=>x.id===d.smartLog);if(!s)return;const id=s.id;
  if(s.done)return;
  if(a.sportVersion===4){const actual={};for(const input of document.querySelectorAll('[data-sport-actual]'))if(input.dataset.setId===id)actual[input.dataset.sportActual]=input.value;const kind=document.querySelector(`[data-smart-kind="${CSS.escape(id)}"]`)?.value||s.kind||'working';sportPendingInputs[id]={actual,kind};sportRememberInput();try{const command=PathSportCore.prepare(data,{type:'logSet',activeId:a.id,setId:id,actual,kind},{id:uid});if(sportTry(()=>PathSportCore.apply(data,command,{prepared:true}))){sportClearInput();delete sportSetErrors[id];const button=[...document.querySelectorAll('[data-smart-log]')].find(b=>b.dataset.smartLog===id);if(button)PathMotion.check(button,true);}else{sportSetErrors[id]=sportText('saveError');render();}}catch(error){sportSetErrors[id]=sportError(error);render();}return;}
  const value=document.querySelector(`[data-smart-result="${id}"]`)?.value??s.result,kind=document.querySelector(`[data-smart-kind="${id}"]`)?.value||s.kind||'working';
  try{const copy=pathClone(a);for(const [pendingId,pending] of Object.entries(sportPendingInputs)){const pendingSet=copy.sets.find(x=>x.id===pendingId&&!x.done);if(pendingSet)Object.assign(pendingSet,pending);}sportLogSet(copy,id,value,kind);delete sportSetErrors[id];sportPendingInputs[id]={result:value,kind};sportRememberInput();if(mutate(()=>{data.activeWorkout=copy;})){sportClearInput();const button=document.querySelector(`[data-smart-log="${id}"]`);if(button)PathMotion.check(button,true);document.querySelector('[data-smart-result]:not(:disabled)')?.focus({preventScroll:true});}else{sportSetErrors[id]='Could not save. Your input draft is retained. Retry.';render();}}catch(error){sportSetErrors[id]=error.message;render();document.querySelector(`[data-smart-result="${id}"]`)?.focus();}return;
 }
 if(d.sportShort)return sportOpenShort(d.sportShort,d.calendarId);
 if('sportShortClose'in d){sportShortDraft=null;render();return;}
 if(d.sportShortSlot){sportShortDraft.start=Number(d.sportShortSlot);render();return;}
 if(d.sportShortApply)return sportCommitShort(Number(d.sportShortApply));
 if('sportMoveFull'in d)return sportFindFullSlot();
 if('sportMoveConfirm'in d)return sportCommitFullSlot();
});
