const sportEditorRenderBefore=renderEditor;
renderEditor=function(){sportEditorRenderBefore();if(!editor||!['Exercise settings','Program notes','Swap this session only','Add existing exercise','Planche test','Front Lever test','Review next target'].includes(editor.title))return;const form=document.querySelector('#editor-form'),more=form?.querySelector('.context-more');for(const f of editor.fields){if(f.step!==undefined)form?.querySelector(`[name="${f.key}"]`)?.setAttribute('step',String(f.step));}if(more){for(const field of [...more.querySelectorAll('.field')])more.before(field);more.remove();}pathContextPosition();};
